xpath.script:
(function(){
  function init(){
    var sel=document.getElementById('pkPriceList');
    var precio=document.querySelector('input[name="price"]');
    var form=precio && precio.form;
    if(!sel||!precio||!form) return;
    function val(n){ var i=form.querySelector('input[name="'+n+'"]:checked'); return i?i.value:''; }
    function fill(){
      var pl=sel.value;
      if(!pl){ precio.readOnly=false; return; }
      precio.readOnly=true;
      var p=val('presentation'), t=val('size_grade_id');
      if(!p||!t){ return; }
      fetch('/marketplace/list-price',{method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',method:'call',
          params:{price_list_ref:pl,presentation:p,size_grade_id:t}})})
        .then(function(r){return r.json();}).then(function(d){
          var r=(d&&d.result)||{};
          if(r.precio!=null){
            precio.value=r.precio.toFixed(2);
            precio.dispatchEvent(new Event('input',{bubbles:true}));
          }
        }).catch(function(){});
    }
    form.addEventListener('change', function(e){
      var n=e.target && e.target.name;
      if(e.target===sel || n==='presentation' || n==='size_grade_id'){ fill(); }
    });
    fill();
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
})();

(function(){
  function init(){
    var precio = document.querySelector('input[name="price"]');
    var form = precio && precio.form;
    var caja  = document.getElementById('pk_sugerencia');
    if(!precio || !form || !caja) return;
    var txt = caja.querySelector('.pk-sug-txt');
    var usar = caja.querySelector('.pk-sug-usar');
    var ultimo = null;
    function val(n){ var i=form.querySelector('input[name="'+n+'"]:checked'); return i?i.value:''; }

    // `partes` es una lista de [texto, negrita]. Se arma con nodos de texto:
    // el nombre de la empacadora lo escribe ella misma en su perfil y antes
    // entraba crudo en innerHTML (XSS en la pantalla de publicar).
    function mostrar(partes, valor){
      while (txt.firstChild) { txt.removeChild(txt.firstChild); }
      partes.forEach(function(p){
        var nodo = p[1] ? document.createElement('strong') : document.createElement('span');
        nodo.textContent = String(p[0] == null ? '' : p[0]);
        txt.appendChild(nodo);
      });
      caja.style.display = 'flex';
      ultimo = valor;
      usar.style.display = (valor && !precio.disabled) ? 'inline-flex' : 'none';
    }
    function consultar(){
      var p = val('presentation'), t = val('size_grade_id');
      var blk = document.getElementById('pfPresBlk');
      if(!p || !t || (blk && blk.hidden)){ caja.style.display = 'none'; return; }
      fetch('/marketplace/suggested-price', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call',
                              params:{presentation: p, size_grade_id: t}})
      }).then(function(r){ return r.json(); }).then(function(d){
        var r = (d && d.result) || {};
        if(r.precio){
          var u = r.uom === 'kg' ? 'Kg' : 'Lb';
          var extra = r.cuantas > 1 ? (' · ' + r.cuantas + ' empacadoras cotizan esta talla') : '';
          mostrar([[r.empacadora, true], [' te paga ', false],
                   ['$' + Number(r.precio).toFixed(2) + ' / ' + u, true],
                   [' por esta talla' + extra, false]],
                  r.precio);
        } else if(r.sin_precio){
          mostrar([['Ninguna de tus ' + Number(r.listas || 0) + ' lista(s) vigente(s) cotiza esta talla.', false]], null);
        } else {
          caja.style.display = 'none';
        }
      }).catch(function(){ caja.style.display = 'none'; });
    }
    usar.addEventListener('click', function(){
      if(ultimo && !precio.readOnly){
        precio.value = Number(ultimo).toFixed(2);
        precio.dispatchEvent(new Event('input', {bubbles: true}));
        precio.focus();
      }
    });
    form.addEventListener('change', function(e){
      var n = e.target && e.target.name;
      // setTimeout: deja que el formulario limpie presentación/talla al
      // pasar a una etapa sin talla comercial antes de consultar.
      if(n === 'presentation' || n === 'size_grade_id' || n === 'stage_id'){ setTimeout(consultar, 0); }
    });
    consultar();
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); }
  else { init(); }
})();
